#!/usr/bin/env bash
# check-contracts-semver.sh — mechanical API semver gate for the per-major
# contracts/ layout (issue #693, child (b) of epic #684).
#
# Enforces, on every PR that touches contracts/:
#
#  1. The VERSION TRIANGLE — for each live major contracts/vN/openapi.yaml, the
#     spec's info.version major, the vN directory, and the URL major in the
#     first servers: entry must all agree. (The npm spec-package version is the
#     third leg by construction — spec-publish.yml publishes info.version — so a
#     committed disagreement can only appear among these three locations.)
#
#  2. BUMP CLASSIFICATION — oasdiff classifies each CHANGED major's diff against
#     the base ref as breaking / additive / editorial, and the info.version bump
#     must be sufficient for the change:
#       - breaking  -> never an in-place edit: ship a NEW major directory
#                      contracts/v(N+1)/ (absent at base => allowed); an in-place
#                      breaking change to an existing major is rejected outright.
#       - additive  -> at least a MINOR bump.
#       - editorial -> at least a PATCH bump (so the changed spec republishes;
#                      an editorial change with NO bump would merge but never
#                      publish — silent consumer drift).
#     A major UNCHANGED vs the base ref has no bump requirement (an unrelated
#     major on a multi-major PR is not forced to bump). Old (non-newest) majors
#     are FROZEN: only editorial changes are allowed; a breaking or additive
#     in-place edit is rejected (ship a new major instead). Deleting a major that
#     was live at the base ref is rejected here — retirement is the #708 flow.
#
# The version bump itself is normalized OUT of the classification diff (info.version
# is not an oasdiff --exclude-elements element), so a bumped editorial change
# classifies editorial, not additive.
#
# oasdiff integration: `breaking -f json` -> JSON array of breaking (ERR+WARN)
# changes; `diff -f json --exclude-elements <cosmetics>` -> empty object means
# the residual change was editorial only. Any oasdiff error FAILS CLOSED (exit 3),
# never silently "editorial". The DECISION logic is unit-tested with a stub
# oasdiff on PATH (tests/check-contracts-semver.bats); the real-oasdiff behaviour
# is exercised by the workflow in CI.
#
# Exit codes: 0 = pass, 1 = semver violation(s), 2 = usage / bad base ref,
# 3 = oasdiff tool error.
#
# Generated by /development:bootstrap when an OpenAPI surface is detected; the
# workflow (.github/workflows/contracts-semver.yml) is the primary caller and
# this script's exit code gates it. Source template:
# development/skills/bootstrap/templates/common/.github/scripts/check-contracts-semver.sh
set -euo pipefail

BASE_REF=""
CONTRACTS_DIR="contracts"
OASDIFF="${OASDIFF:-oasdiff}"
OUTPUT=""

usage() {
    echo "usage: check-contracts-semver.sh --base-ref <ref> [--contracts-dir <dir>] [--output <file>]" >&2
    exit 2
}

while [[ $# -gt 0 ]]; do
    case "$1" in
    --base-ref)
        [[ $# -ge 2 ]] || usage
        BASE_REF="$2"
        shift 2
        ;;
    --contracts-dir)
        [[ $# -ge 2 ]] || usage
        CONTRACTS_DIR="$2"
        shift 2
        ;;
    --oasdiff)
        [[ $# -ge 2 ]] || usage
        OASDIFF="$2"
        shift 2
        ;;
    --output)
        [[ $# -ge 2 ]] || usage
        OUTPUT="$2"
        shift 2
        ;;
    -h | --help) usage ;;
    *)
        echo "unknown flag: $1" >&2
        usage
        ;;
    esac
done

[[ -n "$BASE_REF" ]] || {
    echo "::error::--base-ref is required" >&2
    usage
}
CONTRACTS_DIR="${CONTRACTS_DIR%/}"

# An unresolvable base ref would make every major look "new" and silently pass
# the whole bump-classification half — fail closed instead.
git rev-parse --verify --quiet "${BASE_REF}^{commit}" >/dev/null 2>&1 || {
    echo "::error::base ref '${BASE_REF}' does not resolve" >&2
    exit 2
}

# Cosmetic elements an "editorial" change may touch without counting as additive.
COSMETIC_ELEMENTS="examples,description,title,summary,extensions"

# --- helpers -----------------------------------------------------------------

is_number() { [[ "$1" =~ ^[0-9]+$ ]]; }

# spec_version FILE -> the info.version scalar (empty if absent), single-lined.
spec_version() {
    local v
    v="$(yq -r '.info.version // ""' "$1" 2>/dev/null || true)"
    [[ "$v" == "null" ]] && v=""
    printf '%s' "${v//$'\n'/ }"
}

# servers_major FILE -> the vN major digits from the first servers: url, empty if
# none. The `|| true` keeps a no-match grep from leaking exit 1 as the function's
# status (which set -e would treat as a fatal error at the call site).
servers_major() {
    local url
    url="$(yq -r '.servers[0].url // ""' "$1" 2>/dev/null || true)"
    [[ "$url" == "null" ]] && url=""
    printf '%s' "$url" | { grep -oE 'v[0-9]+' || true; } | tail -n1 | tr -d 'v'
}

# semver_bump OLD NEW -> major | minor | patch | none | down (invalid -> down).
semver_bump() {
    local old="$1" new="$2" oM om op nM nm np
    IFS=. read -r oM om op _ <<<"${old}.0.0"
    IFS=. read -r nM nm np _ <<<"${new}.0.0"
    op="${op%%[-+]*}" # strip any pre-release/build suffix (e.g. 1.2.3-rc1)
    np="${np%%[-+]*}"
    if ! is_number "$oM" || ! is_number "$om" || ! is_number "$op" ||
        ! is_number "$nM" || ! is_number "$nm" || ! is_number "$np"; then
        echo "down"
        return
    fi
    if ((nM > oM)); then
        echo "major"
    elif ((nM < oM)); then
        echo "down"
    elif ((nm > om)); then
        echo "minor"
    elif ((nm < om)); then
        echo "down"
    elif ((np > op)); then
        echo "patch"
    elif ((np < op)); then
        echo "down"
    else echo "none"; fi
}

# classify BASE HEAD -> breaking | additive | editorial | __ERROR__.
# We pass no --fail-on/-o, so a clean oasdiff run always exits 0; a non-zero
# status therefore means a genuine tool error. classify runs inside a command
# substitution, so it CANNOT rely on `exit` or errexit propagation (errexit is
# not inherited into $(...) without inherit_errexit, which bash 3.2 lacks) — it
# checks each status explicitly and returns the __ERROR__ sentinel, which the
# caller turns into a fail-closed exit 3.
classify() {
    local base="$1" head="$2" out n diff
    if ! out="$("$OASDIFF" breaking -f json "$base" "$head" 2>/dev/null)"; then
        echo "__ERROR__"
        return 0
    fi
    n="$(jq 'length' <<<"${out:-[]}" 2>/dev/null || echo "bad")"
    if [[ "$n" == "bad" ]]; then
        echo "__ERROR__"
        return 0
    fi
    if is_number "$n" && ((n > 0)); then
        echo "breaking"
        return 0
    fi
    if ! diff="$("$OASDIFF" diff -f json --exclude-elements "$COSMETIC_ELEMENTS" "$base" "$head" 2>/dev/null)"; then
        echo "__ERROR__"
        return 0
    fi
    if [[ -z "$diff" ]] || jq -e 'length == 0' >/dev/null 2>&1 <<<"$diff"; then
        echo "editorial"
    else
        echo "additive"
    fi
}

# --- discover majors ---------------------------------------------------------

shopt -s nullglob
majors=()
for d in "$CONTRACTS_DIR"/v[0-9]*/; do
    m="$(basename "$d")"
    is_number "${m#v}" || continue # skip vNbeta / v1.bak / …
    [[ -f "${d}openapi.yaml" ]] && majors+=("$m")
done

# Majors live at the base ref — to catch a removed (retired) frozen major.
base_majors=()
while IFS= read -r p; do
    [[ -z "$p" ]] && continue
    bm="$(basename "$(dirname "$p")")"
    is_number "${bm#v}" && base_majors+=("$bm")
done < <(git ls-tree -r --name-only "$BASE_REF" -- "$CONTRACTS_DIR" 2>/dev/null |
    grep -E "^${CONTRACTS_DIR}/v[0-9]+/openapi\.yaml$" || true)

violations=()
add_violation() {
    violations+=("$1")
    echo "::error::$1"
}

write_findings() {
    [[ -n "$OUTPUT" ]] || return 0
    local mj
    mj="$(printf '%s\n' "${majors[@]+"${majors[@]}"}" | jq -R . | jq -cs 'map(select(length > 0))')"
    printf '%s\n' "${violations[@]+"${violations[@]}"}" | jq -R . |
        jq -cs --argjson majors "$mj" '{violations: map(select(length > 0)), majors: $majors}' >"$OUTPUT"
}

finish() {
    write_findings
    if [[ ${#violations[@]} -gt 0 ]]; then
        echo "Contract semver gate FAILED with ${#violations[@]} violation(s)." >&2
        exit 1
    fi
    echo "Contract semver gate passed."
    exit 0
}

# A major present at base but gone at head — retiring a live major is #708's flow.
for bm in "${base_majors[@]+"${base_majors[@]}"}"; do
    found=0
    for m in "${majors[@]+"${majors[@]}"}"; do [[ "$m" == "$bm" ]] && found=1 && break; done
    ((found == 0)) &&
        add_violation "${CONTRACTS_DIR}/${bm}/openapi.yaml: major ${bm} was live at ${BASE_REF} but removed — retiring a live major is the #708 retirement flow, not an in-place delete"
done

if [[ ${#majors[@]} -eq 0 ]]; then
    echo "No ${CONTRACTS_DIR}/vN/openapi.yaml at HEAD — nothing further to gate."
    finish
fi

# Newest major = highest N; every lower major is frozen.
newest=0
for m in "${majors[@]}"; do
    n="${m#v}"
    ((n > newest)) && newest="$n"
done

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

for m in "${majors[@]}"; do
    n="${m#v}"
    spec="${CONTRACTS_DIR}/${m}/openapi.yaml"
    version="$(spec_version "$spec")"
    smajor="$(servers_major "$spec")"

    # --- version triangle ---
    vmajor="${version%%.*}"
    if [[ -z "$version" ]]; then
        add_violation "${spec}: missing info.version"
    elif [[ "$vmajor" != "$n" ]]; then
        add_violation "${spec}: info.version (${version}) major disagrees with directory ${m}"
    fi
    if [[ -z "$smajor" ]]; then
        add_violation "${spec}: servers[0].url has no /vN major segment"
    elif [[ "$smajor" != "$n" ]]; then
        add_violation "${spec}: servers major (v${smajor}) disagrees with directory ${m}"
    fi

    # --- bump classification vs the base ref ---
    if ! git cat-file -e "${BASE_REF}:${spec}" 2>/dev/null; then
        if [[ "$n" -lt "$newest" ]]; then
            echo "${spec}: backfilled historical major ${m} (absent at ${BASE_REF}) — frozen from birth."
        else
            echo "${spec}: new major ${m} (absent at ${BASE_REF}) — no diff classification."
        fi
        continue
    fi

    git show "${BASE_REF}:${spec}" >"${tmp}/base.yaml"
    base_version="$(spec_version "${tmp}/base.yaml")"

    # Unchanged vs base -> no bump requirement (an untouched major on a
    # multi-major PR must not be forced to bump).
    if cmp -s "${tmp}/base.yaml" "$spec"; then
        continue
    fi

    # Neutralize the version bump so it does not itself register as a structural
    # (additive) change — info.version is not an oasdiff exclude-element.
    cp "$spec" "${tmp}/norm_head.yaml"
    if [[ -n "$base_version" ]]; then
        yq -i ".info.version = \"${base_version}\"" "${tmp}/norm_head.yaml" 2>/dev/null || true
    fi
    class="$(classify "${tmp}/base.yaml" "${tmp}/norm_head.yaml")"
    if [[ "$class" == "__ERROR__" ]]; then
        echo "::error::oasdiff failed classifying ${spec} — failing the gate closed" >&2
        exit 3
    fi
    bump="$(semver_bump "$base_version" "$version")"
    frozen=0
    [[ "$n" -ne "$newest" ]] && frozen=1

    if [[ "$bump" == "down" ]]; then
        add_violation "${spec}: info.version went backwards or is invalid (${base_version} -> ${version})"
    fi

    case "$class" in
    breaking)
        if ((frozen)); then
            add_violation "${spec}: major ${m} is frozen (not newest) — a breaking change is not allowed; ship a new major"
        else
            add_violation "${spec}: breaking change to major ${m} — a breaking change is never an in-place edit; ship a NEW major directory contracts/v$((n + 1))/ and revert this edit"
        fi
        ;;
    additive)
        if ((frozen)); then
            add_violation "${spec}: major ${m} is frozen (not newest) — an additive change is not allowed; ship a new major"
        elif [[ "$bump" != "major" && "$bump" != "minor" ]]; then
            add_violation "${spec}: additive change requires at least a MINOR bump, got ${bump} (${base_version} -> ${version})"
        fi
        ;;
    editorial)
        # Frozen majors accept editorial edits. Any editorial change must still
        # bump so the changed spec republishes (no bump => silent drift).
        if [[ "$bump" == "none" ]]; then
            add_violation "${spec}: editorial change requires at least a PATCH bump so the spec republishes (${base_version} -> ${version})"
        fi
        ;;
    esac
done

finish
